PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?total_shortfall ?total_cash_flow ?de_risk_action_count
WHERE {
  # Investor base
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  # Aggregate shortfall per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?total_shortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:shortfall ?shortfall ;
            wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  # Aggregate cash flow per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?total_cash_flow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:amount ?amount ;
          wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  # Count De?risking actions per investor
  {
    SELECT ?investorId (COUNT(?ra) AS ?de_risk_action_count)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:action ?action ;
          wm:investorId ?investorId .
      FILTER(LCASE(STR(?action)) = "de-risking")
    }
    GROUP BY ?investorId
  }

  # Apply required filters
  FILTER(?total_shortfall > 0 && ?total_cash_flow < 0 && ?de_risk_action_count > 0)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avgSharpe ?avgVol ?totalHoldingGain ?netCashFlow
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:investorId ?investorId . }
  OPTIONAL { ?investor wm:investorName ?investorName . }

  {
    SELECT ?investor (AVG(xsd:decimal(?sharpe)) AS ?avgSharpe) (AVG(xsd:decimal(?vol)) AS ?avgVol)
    WHERE {
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:avgSharpeRatio ?sharpe .
      ?goal wm:avgVolatilityPct ?vol .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain)
    WHERE {
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:currentValue ?curr .
      ?holding wm:cost ?cost .
      BIND (xsd:decimal(?curr) - xsd:decimal(?cost) AS ?gain)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor .
      ?cashFlow wm:amount ?amount .
    }
    GROUP BY ?investor
  }

  FILTER ( ?avgSharpe < 0 && ?avgVol > 10 && ?totalHoldingGain < 0 && ?netCashFlow < 1000000 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?total_score WHERE {
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?cashAmount)) AS ?cash_flow_sum) WHERE {
      ?cashFlow a wm:CashFlow .
      ?cashFlow wm:amount ?cashAmount .
      ?cashFlow wm:cashFlowOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?rebalanceAmount)) AS ?rebalancing_sum) WHERE {
      ?rebalance a wm:RebalancingAction .
      ?rebalance wm:amount ?rebalanceAmount .
      ?rebalance wm:rebalancingActionOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?scenario_change_sum) WHERE {
      ?scenario a wm:ScenarioRebalancing .
      ?scenario wm:newAllocationPct ?newAlloc .
      ?scenario wm:currentAllocationPct ?currAlloc .
      ?scenario wm:scenarioRebalancingOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
    } GROUP BY ?investorId
  }

  BIND( COALESCE(?cash_flow_sum, 0) + COALESCE(?rebalancing_sum, 0) + COALESCE(?scenario_change_sum, 0) AS ?total_score )
}
ORDER BY DESC(?total_score) ?investorId
LIMIT 10

